<script setup lang="ts">
import{computed,onMounted,ref}from'vue';import UiStatePanel from'./UiStatePanel.vue';import ConfirmDialog from'./ConfirmDialog.vue';import'../crawler-runtime.css';
type State='loading'|'ready'|'empty'|'error'|'expired'|'forbidden'|'blocked';type RunStatus='running'|'succeeded'|'blocked'|'failed'|'timed_out'|'cancelled';
interface Lease{run_id:string;lease_owner:string;leased_at:string;heartbeat_at:string;expires_at:string}interface Profile{id:string;code:string;name:string;provider_id:string;provider_name:string;status:string;lease:Lease|null}interface Run{id:string;organization_id:string;workspace_id:string;provider_id:string;crawler_profile_id:string;status:RunStatus;page_count:number;item_count:number;detail_count:number;duration_ms:number|null;error_code:string|null;request_id:string;trace_id:string;started_at:string;finished_at:string|null}
const props=defineProps<{apiBaseUrl:string}>(),state=ref<State>('loading'),profiles=ref<Profile[]>([]),runs=ref<Run[]>([]),requestId=ref(''),message=ref(''),query=ref(''),status=ref('all'),confirming=ref(false),saving=ref(false);const activeLeases=computed(()=>profiles.value.filter(item=>item.lease)),blockedRuns=computed(()=>runs.value.filter(item=>['blocked','failed','timed_out'].includes(item.status))),filtered=computed(()=>runs.value.filter(item=>(status.value==='all'||item.status===status.value)&&(!query.value||[item.id,item.error_code,item.trace_id].some(value=>value?.toLowerCase().includes(query.value.toLowerCase())))));const failure=(code:number):State=>code===401?'expired':code===403?'forbidden':[408,425,429,502,503,504].includes(code)?'blocked':'error';
async function load(){state.value='loading';message.value='';try{const response=await fetch(`${props.apiBaseUrl}/platform/crawler-runtime`,{credentials:'include',headers:{accept:'application/json'}}),body=await response.json().catch(()=>null);requestId.value=body?.request_id??'';if(!response.ok){state.value=failure(response.status);return;}profiles.value=body.data.profiles;runs.value=body.data.runs;state.value=profiles.value.length||runs.value.length?'ready':'empty';}catch{state.value='blocked';}}
async function recover(){saving.value=true;try{const response=await fetch(`${props.apiBaseUrl}/platform/crawler-runtime/recover-expired`,{method:'POST',credentials:'include',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:'{}'}),body=await response.json().catch(()=>null);requestId.value=body?.request_id??'';message.value=response.ok?`已回收 ${body.data.recovered} 个过期租约`:body?.error?.action_hint??'回收未完成';if(response.ok)await load();}catch{message.value='依赖不可用，未执行回收';}finally{saving.value=false;confirming.value=false;}}
const time=(value:string|null)=>value?new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(value)):'—';onMounted(load);
</script>
<template><section class="crawler-center" aria-labelledby="crawler-title"><header class="crawler-title"><div><p>PLAYWRIGHT CRAWLER</p><h2 id="crawler-title">采集运行监控</h2><span>浏览器档案按平台全局租约互斥；运行记录保留组织与工作区范围。</span></div><button type="button" :disabled="saving" @click="confirming=true">回收过期租约</button></header><UiStatePanel v-if="state!=='ready'" :kind="state" :request-id="requestId" @primary="load"/><template v-else><div class="crawler-metrics"><article><small>浏览器档案</small><strong>{{profiles.length}}</strong><span>仅展示元数据</span></article><article><small>活动租约</small><strong>{{activeLeases.length}}</strong><span>同一档案仅一个</span></article><article><small>异常运行</small><strong>{{blockedRuns.length}}</strong><span>不会自动绕过限制</span></article></div><section class="crawler-leases"><header><h3>档案与租约</h3><span>{{message||'租约令牌与凭证明文从不返回页面'}}</span></header><div class="crawler-profile-grid"><article v-for="profile in profiles" :key="profile.id" :data-leased="Boolean(profile.lease)"><i></i><div><strong>{{profile.name}}</strong><small>{{profile.provider_name}} · {{profile.code}}</small></div><span>{{profile.lease?'使用中':profile.status==='active'?'可用':'已停用'}}</span><dl v-if="profile.lease"><div><dt>实例</dt><dd>{{profile.lease.lease_owner}}</dd></div><div><dt>到期</dt><dd>{{time(profile.lease.expires_at)}}</dd></div></dl></article></div></section><section class="crawler-runs"><header><div><h3>最近运行</h3><span>运行、拦截和失败均保留 request_id / trace_id</span></div><div><input v-model="query" aria-label="搜索运行" placeholder="运行 ID / 错误码 / trace_id"><select v-model="status" aria-label="运行状态"><option value="all">全部状态</option><option value="running">运行中</option><option value="succeeded">成功</option><option value="blocked">已拦截</option><option value="failed">失败</option><option value="timed_out">已超时</option><option value="cancelled">已取消</option></select></div></header><div class="crawler-table-wrap"><table><thead><tr><th>运行</th><th>范围</th><th>状态</th><th>采集量</th><th>耗时</th><th>开始时间</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id"><td><strong>{{item.id.slice(0,8)}}</strong><small>{{item.error_code||item.trace_id.slice(0,12)}}</small></td><td><span>{{item.organization_id.slice(0,8)}}</span><small>{{item.workspace_id.slice(0,8)}}</small></td><td><b :data-status="item.status">{{item.status}}</b></td><td>{{item.item_count}} 条<small>{{item.page_count}} 页 · {{item.detail_count}} 详情</small></td><td>{{item.duration_ms===null?'—':`${item.duration_ms} ms`}}</td><td>{{time(item.started_at)}}</td></tr><tr v-if="!filtered.length"><td colspan="6">当前筛选没有运行记录。</td></tr></tbody></table></div></section></template><ConfirmDialog :open="confirming" title="回收所有已过期租约？" description="仅回收服务端确认已经过期的档案租约，并把对应运行标记为超时。" impact="不会终止有效租约，不会删除运行历史、浏览器档案或凭证。" confirm-label="确认回收" confirmation-text="确认回收" @cancel="confirming=false" @confirm="recover"/></section></template>
